def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))

    colors = []
    for color, _ in objects:
        if color not in colors:
            colors.append(color)

    # Put each color's two pieces into its own bottom lane.
    # The color whose first piece is in the upper-left half goes in the left lane.
    def color_key(color):
        cells = [p for col, obj in objects if col == color for p in obj]
        return sum(c for r, c in cells) / len(cells)

    ordered = sorted(colors, key=color_key)
    lanes = {ordered[0]: 0, ordered[-1]: 5}
    out = [[0] * w for _ in range(h)]

    for color in colors:
        group = [cells for col, cells in objects if col == color]
        group.sort(key=lambda cells: min(r for r, c in cells))
        for i, cells in enumerate(group):
            minr = min(r for r, c in cells)
            minc = min(c for r, c in cells)
            height = max(r for r, c in cells) - minr + 1
            top = 5 if i == 0 else 8
            if top + height > h:
                top = h - height
            for r, c in cells:
                y = top + r - minr
                x = lanes[color] + c - minc
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = color
    return out
